BEGIN;
CREATE TABLE IF NOT EXISTS articles (
 id VARCHAR(32) PRIMARY KEY,
 kind VARCHAR(20) NOT NULL CHECK (kind IN ('recruitment','story','announcement','news')),
 status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','hidden')),
 draft JSONB NOT NULL,
 published JSONB,
 version INTEGER NOT NULL DEFAULT 1 CHECK (version>=1),
 blocked_by_admin BOOLEAN NOT NULL DEFAULT FALSE,
 hidden_reason TEXT NOT NULL DEFAULT '',
 created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
 updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 published_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS article_one_featured_kind ON articles(kind) WHERE status='published' AND kind IN ('recruitment','story');
CREATE TABLE IF NOT EXISTS article_audit (
 id SERIAL PRIMARY KEY,
 article_id VARCHAR(32) REFERENCES articles(id),
 actor_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
 action VARCHAR(40) NOT NULL,
 details JSONB NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS recruitment_positions (
 position VARCHAR(30) PRIMARY KEY CHECK (position IN ('shipper','packing','customer_support','communications')),
 is_open BOOLEAN NOT NULL DEFAULT TRUE,
 version INTEGER NOT NULL DEFAULT 1,
 updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
 updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
INSERT INTO recruitment_positions(position) VALUES ('shipper'),('packing'),('customer_support'),('communications') ON CONFLICT(position) DO NOTHING;
-- Preserve existing story/recruitment copy; never overwrite manager edits.
INSERT INTO articles(id,kind,status,draft,published,published_at) VALUES ('initial-story','story','published','{"title": "Câu chuyện của chúng tôi", "summary": "Từ những trăn trở tại canteen trường đến giải pháp công nghệ vì sinh viên NEU.", "cover_url": "", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ở một buổi trưa vội vã nơi giảng đường đông đúc, khi chuông báo giờ ra chơi vừa vang lên, dòng sinh viên lại đổ xuống canteen như một cơn sóng quen thuộc. Những hàng người nối dài, tiếng gọi món dồn dập, nhưng đi kèm với đó là sự quá tải và chậm trễ. Không ít sinh viên đành quay trở lại lớp khi chưa kịp ăn gì. Ở các tầng cao như 7, 8, 9, 10, nhiều bạn thậm chí từ bỏ việc xuống canteen, bởi chỉ riêng việc di chuyển đã tiêu tốn gần hết khoảng thời gian nghỉ ngắn ngủi."}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“Dù lượng sinh viên đông, nhu cầu cao, nhưng chất lượng trải nghiệm bữa ăn phải là ưu tiên số một. Nếu giảm được thời gian chờ đợi, sinh viên sẽ có bữa trưa trọn vẹn và tràn đầy năng lượng.”"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Đứng phía sau quầy phục vụ, chị Hương - một nhân viên lâu năm của canteen NEU - chứng kiến tình trạng này diễn ra mỗi ngày. Chị nhận ra một vấn đề lớn: dù lượng sinh viên đông, nhu cầu cao, nhưng doanh thu của canteen vẫn chưa tương xứng. Nguyên nhân không nằm ở chất lượng món ăn, mà ở cách vận hành chưa tối ưu. Những giờ cao điểm thì quá tải, còn những thời điểm khác lại dư thừa đồ ăn. Việc phục vụ hoàn toàn thủ công khiến quá trình bán hàng bị gián đoạn, mất đi nhiều cơ hội phục vụ khách hàng."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Chị Hương bắt đầu suy nghĩ nghiêm túc hơn về việc thay đổi. Nếu có thể giảm thời gian chờ đợi, phân bổ đơn hàng hợp lý và giúp sinh viên tiếp cận đồ ăn dễ dàng hơn, thì không chỉ trải nghiệm được cải thiện mà hiệu quả của canteen cũng sẽ tăng lên đáng kể. Và rồi một câu hỏi xuất hiện: liệu công nghệ có thể giải quyết tất cả những điều đó?"}]}, {"type": "heading", "content": [{"type": "text", "text": "Khởi nguồn của NEUFood"}], "attrs": {"level": 3}}, {"type": "paragraph", "content": [{"type": "text", "text": "Giải pháp đặt món trước, giao tận phòng học và theo dõi trực tiếp tiến trình đơn hàng giúp tối ưu 100% thời gian nghỉ giữa giờ cho giảng viên và sinh viên."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Từ ý tưởng ấy, NEUFood ra đời - nền tảng đặt đồ ăn trực tuyến dành riêng cho sinh viên trong trường. Thông qua hệ thống này, sinh viên có thể xem thực đơn, đặt món trước và lựa chọn thời gian nhận phù hợp. Điều này giúp giảm đáng kể tình trạng chen lấn, đồng thời phân tán lượng khách theo từng khung giờ, giúp canteen vận hành mượt mà hơn."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Không dừng lại ở đó, NEUFood còn giúp canteen quản lý đơn hàng một cách khoa học, dự đoán nhu cầu theo thời điểm, từ đó chuẩn bị nguyên liệu hợp lý, giảm lãng phí và tối ưu chi phí. Nhờ vậy, hiệu quả không chỉ tăng về số lượng đơn hàng mà còn tăng về tính bền vững."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Và từ đó, mỗi giờ ra chơi không còn là áp lực thời gian, mà trở thành một khoảng nghỉ đúng nghĩa - nơi chỉ cần một cú chạm trên điện thoại, bữa ăn nóng hổi đã sẵn sàng phục vụ bạn ngay tại giảng đường."}]}]}, "recruitment_roles": []}'::jsonb,'{"title": "Câu chuyện của chúng tôi", "summary": "Từ những trăn trở tại canteen trường đến giải pháp công nghệ vì sinh viên NEU.", "cover_url": "", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ở một buổi trưa vội vã nơi giảng đường đông đúc, khi chuông báo giờ ra chơi vừa vang lên, dòng sinh viên lại đổ xuống canteen như một cơn sóng quen thuộc. Những hàng người nối dài, tiếng gọi món dồn dập, nhưng đi kèm với đó là sự quá tải và chậm trễ. Không ít sinh viên đành quay trở lại lớp khi chưa kịp ăn gì. Ở các tầng cao như 7, 8, 9, 10, nhiều bạn thậm chí từ bỏ việc xuống canteen, bởi chỉ riêng việc di chuyển đã tiêu tốn gần hết khoảng thời gian nghỉ ngắn ngủi."}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "“Dù lượng sinh viên đông, nhu cầu cao, nhưng chất lượng trải nghiệm bữa ăn phải là ưu tiên số một. Nếu giảm được thời gian chờ đợi, sinh viên sẽ có bữa trưa trọn vẹn và tràn đầy năng lượng.”"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Đứng phía sau quầy phục vụ, chị Hương - một nhân viên lâu năm của canteen NEU - chứng kiến tình trạng này diễn ra mỗi ngày. Chị nhận ra một vấn đề lớn: dù lượng sinh viên đông, nhu cầu cao, nhưng doanh thu của canteen vẫn chưa tương xứng. Nguyên nhân không nằm ở chất lượng món ăn, mà ở cách vận hành chưa tối ưu. Những giờ cao điểm thì quá tải, còn những thời điểm khác lại dư thừa đồ ăn. Việc phục vụ hoàn toàn thủ công khiến quá trình bán hàng bị gián đoạn, mất đi nhiều cơ hội phục vụ khách hàng."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Chị Hương bắt đầu suy nghĩ nghiêm túc hơn về việc thay đổi. Nếu có thể giảm thời gian chờ đợi, phân bổ đơn hàng hợp lý và giúp sinh viên tiếp cận đồ ăn dễ dàng hơn, thì không chỉ trải nghiệm được cải thiện mà hiệu quả của canteen cũng sẽ tăng lên đáng kể. Và rồi một câu hỏi xuất hiện: liệu công nghệ có thể giải quyết tất cả những điều đó?"}]}, {"type": "heading", "content": [{"type": "text", "text": "Khởi nguồn của NEUFood"}], "attrs": {"level": 3}}, {"type": "paragraph", "content": [{"type": "text", "text": "Giải pháp đặt món trước, giao tận phòng học và theo dõi trực tiếp tiến trình đơn hàng giúp tối ưu 100% thời gian nghỉ giữa giờ cho giảng viên và sinh viên."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Từ ý tưởng ấy, NEUFood ra đời - nền tảng đặt đồ ăn trực tuyến dành riêng cho sinh viên trong trường. Thông qua hệ thống này, sinh viên có thể xem thực đơn, đặt món trước và lựa chọn thời gian nhận phù hợp. Điều này giúp giảm đáng kể tình trạng chen lấn, đồng thời phân tán lượng khách theo từng khung giờ, giúp canteen vận hành mượt mà hơn."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Không dừng lại ở đó, NEUFood còn giúp canteen quản lý đơn hàng một cách khoa học, dự đoán nhu cầu theo thời điểm, từ đó chuẩn bị nguyên liệu hợp lý, giảm lãng phí và tối ưu chi phí. Nhờ vậy, hiệu quả không chỉ tăng về số lượng đơn hàng mà còn tăng về tính bền vững."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Và từ đó, mỗi giờ ra chơi không còn là áp lực thời gian, mà trở thành một khoảng nghỉ đúng nghĩa - nơi chỉ cần một cú chạm trên điện thoại, bữa ăn nóng hổi đã sẵn sàng phục vụ bạn ngay tại giảng đường."}]}]}, "recruitment_roles": []}'::jsonb,now()) ON CONFLICT DO NOTHING;
INSERT INTO articles(id,kind,status,draft,published,published_at) VALUES ('initial-recruitment','recruitment','published','{"title": "NEU FOOD ĐANG TUYỂN DỤNG NHÂN SỰ PARTIME", "summary": "Cơ hội việc làm linh hoạt theo lịch học, có thêm thu nhập và môi trường năng động ngay tại trường học.", "cover_url": "", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hiện nay, do nhu cầu đơn hàng tăng cao, NEUFOOD cần tuyển thêm nhân sự để hỗ trợ đóng gói, điều phối, giao món và chăm sóc khách hàng, đồng thời đồng hành trong các hoạt động truyền thông và sự kiện. Đây là cơ hội để các bạn sinh viên vừa có thêm thu nhập, vừa tích lũy kinh nghiệm và rèn luyện kỹ năng làm việc ngay trong khuôn viên trường."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Chúng mình tìm kiếm những sinh viên NEU chủ động, có trách nhiệm, đúng giờ và thân thiện để cùng mang những bữa ăn chu đáo đến cộng đồng sinh viên. Hãy gia nhập ngay đội ngũ NEUFOOD của chúng tôi!"}]}]}, "recruitment_roles": [{"position": "shipper", "description": "Giao món trong khuôn viên NEU, đối chiếu mã nhận hàng và thu COD, cập nhật tình trạng giao hàng."}, {"position": "packing", "description": "Kiểm tra món, số lượng và ghi chú; đóng gói và sắp xếp đơn; phối hợp bàn giao cho khách hoặc shipper."}, {"position": "customer_support", "description": "Giải đáp cách đặt món, tiếp nhận phản hồi và phối hợp chuyển thông tin đến bộ phận phụ trách."}, {"position": "communications", "description": "Viết nội dung, chụp ảnh/quay video và hỗ trợ các hoạt động giới thiệu NEUFood trong trường."}]}'::jsonb,'{"title": "NEU FOOD ĐANG TUYỂN DỤNG NHÂN SỰ PARTIME", "summary": "Cơ hội việc làm linh hoạt theo lịch học, có thêm thu nhập và môi trường năng động ngay tại trường học.", "cover_url": "", "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hiện nay, do nhu cầu đơn hàng tăng cao, NEUFOOD cần tuyển thêm nhân sự để hỗ trợ đóng gói, điều phối, giao món và chăm sóc khách hàng, đồng thời đồng hành trong các hoạt động truyền thông và sự kiện. Đây là cơ hội để các bạn sinh viên vừa có thêm thu nhập, vừa tích lũy kinh nghiệm và rèn luyện kỹ năng làm việc ngay trong khuôn viên trường."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Chúng mình tìm kiếm những sinh viên NEU chủ động, có trách nhiệm, đúng giờ và thân thiện để cùng mang những bữa ăn chu đáo đến cộng đồng sinh viên. Hãy gia nhập ngay đội ngũ NEUFOOD của chúng tôi!"}]}]}, "recruitment_roles": [{"position": "shipper", "description": "Giao món trong khuôn viên NEU, đối chiếu mã nhận hàng và thu COD, cập nhật tình trạng giao hàng."}, {"position": "packing", "description": "Kiểm tra món, số lượng và ghi chú; đóng gói và sắp xếp đơn; phối hợp bàn giao cho khách hoặc shipper."}, {"position": "customer_support", "description": "Giải đáp cách đặt món, tiếp nhận phản hồi và phối hợp chuyển thông tin đến bộ phận phụ trách."}, {"position": "communications", "description": "Viết nội dung, chụp ảnh/quay video và hỗ trợ các hoạt động giới thiệu NEUFood trong trường."}]}'::jsonb,now()) ON CONFLICT DO NOTHING;
INSERT INTO articles(id,kind,status,draft,published,published_at) VALUES ('initial-order-guide','announcement','published','{"title": "Hướng dẫn cách đặt hàng tại hệ thống NEUFood", "summary": "Từ chọn món đến nhận hàng: các bước đặt món, chọn phần thêm, hẹn giờ, xem ưu đãi và thanh toán trên NEUFood.", "cover_url": "", "recruitment_roles": [], "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "NEUFood giúp bạn chọn món trước, nhận tại quầy Canteen A2 hoặc được giao đến địa điểm trong khuôn viên NEU. Hãy làm theo các bước dưới đây để kiểm tra đầy đủ thông tin trước khi gửi đơn."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Đăng nhập và chọn món"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bạn có thể xem thực đơn trước khi đăng nhập. Để thêm món vào giỏ và đặt hàng, hãy đăng nhập tài khoản khách hàng, mở Menu hoặc tìm tên món trên thanh tìm kiếm."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Chọn số lượng và phần thêm"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Mở chi tiết món để xem mô tả, giá và các lựa chọn phần thêm được căn tin hỗ trợ. Mỗi loại phần thêm chỉ chọn một lần cho mỗi suất; giá phần thêm hiển thị ngay trên nút. Các suất cùng món nhưng cấu hình khác nhau sẽ được tách thành những dòng riêng trong giỏ. Đồ uống đóng lon không có phần thêm."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Kiểm tra giỏ hàng và ưu đãi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tại Giỏ hàng, kiểm tra số lượng, phần thêm, giá gốc, khoản giảm giá, phí ship và tổng thanh toán. Món ăn, đồ ăn vặt và đồ uống đều được tính suất theo số lượng; phần thêm không làm tăng số suất. Combo được tính theo số suất đã cấu hình của combo."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Từ 5 suất được freeship; từ 10 suất giảm 6%, từ 20 suất giảm 8%, từ 30 suất giảm 12%. Chỉ áp dụng một mức giảm cao nhất trên toàn bộ tiền hàng, gồm đồ uống và phần thêm; phí giao hàng không thuộc khoản giảm phần trăm."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Chọn cách nhận và kiểm tra người nhận"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Chọn Giao tận nơi hoặc Nhận tại quầy. Nếu giao tận nơi, chọn địa điểm NEU đang được phục vụ và nhập phòng hoặc vị trí nhận cụ thể. Kiểm tra họ tên, số điện thoại người nhận và bổ sung ghi chú khi cần. Khi đặt hộ, hãy sửa thông tin người nhận trước khi xác nhận."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Nhận ngay hoặc đặt hẹn"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Canteen phục vụ từ thứ Hai đến thứ Bảy, nghỉ Chủ nhật. Đặt ngay trong khung nhận đơn 07:30 đến 18:30; món xong sớm có thể được giao sớm. Nếu muốn nhận sau, chọn hẹn giờ trong khung phục vụ 07:30 đến 19:00, cách thời điểm đặt ít nhất 30 phút và trong hôm nay hoặc 7 ngày tiếp theo. Vào Chủ nhật, bạn có thể tạo đơn hẹn nhận vào ngày làm việc hợp lệ tiếp theo."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Xác nhận và thanh toán"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kiểm tra lại chi tiết rồi xác nhận đặt hàng. Tiền mặt hoặc VietQR được thanh toán khi nhận món theo phương thức đã chọn. Với tổng thanh toán từ 500.000đ sau ưu đãi và phí giao thực thu, hệ thống yêu cầu cọc 50% và nhân viên căn tin sẽ gọi xác nhận."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Trong phiên bản thử nghiệm hiện tại, bước đặt cọc chỉ là mô phỏng: chọn Đặt cọc, kiểm tra số tiền, rồi xác nhận đặt cọc mô phỏng. Không chuyển tiền thật theo mã QR mô phỏng. Phần còn lại được hiển thị rõ để thanh toán COD khi nhận."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Theo dõi và nhận món"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Theo dõi tiến trình trong Đơn hàng. Mỗi tài khoản chỉ có một đơn đang hoạt động; hãy hoàn tất đơn hiện tại trước khi tạo đơn mới. Khi nhận món, cung cấp đúng 4 số cuối mã đơn để nhân viên đối chiếu và thanh toán số tiền còn phải thu. Bạn có thể hủy đơn khi đơn vẫn đang chờ xác nhận."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Cần hỗ trợ? Liên hệ anh Hoàng Văn Quản Lý qua số 0812 852 613 để được giải đáp trước khi đặt hàng."}]}]}}'::jsonb,'{"title": "Hướng dẫn cách đặt hàng tại hệ thống NEUFood", "summary": "Từ chọn món đến nhận hàng: các bước đặt món, chọn phần thêm, hẹn giờ, xem ưu đãi và thanh toán trên NEUFood.", "cover_url": "", "recruitment_roles": [], "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "NEUFood giúp bạn chọn món trước, nhận tại quầy Canteen A2 hoặc được giao đến địa điểm trong khuôn viên NEU. Hãy làm theo các bước dưới đây để kiểm tra đầy đủ thông tin trước khi gửi đơn."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Đăng nhập và chọn món"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bạn có thể xem thực đơn trước khi đăng nhập. Để thêm món vào giỏ và đặt hàng, hãy đăng nhập tài khoản khách hàng, mở Menu hoặc tìm tên món trên thanh tìm kiếm."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Chọn số lượng và phần thêm"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Mở chi tiết món để xem mô tả, giá và các lựa chọn phần thêm được căn tin hỗ trợ. Mỗi loại phần thêm chỉ chọn một lần cho mỗi suất; giá phần thêm hiển thị ngay trên nút. Các suất cùng món nhưng cấu hình khác nhau sẽ được tách thành những dòng riêng trong giỏ. Đồ uống đóng lon không có phần thêm."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Kiểm tra giỏ hàng và ưu đãi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tại Giỏ hàng, kiểm tra số lượng, phần thêm, giá gốc, khoản giảm giá, phí ship và tổng thanh toán. Món ăn, đồ ăn vặt và đồ uống đều được tính suất theo số lượng; phần thêm không làm tăng số suất. Combo được tính theo số suất đã cấu hình của combo."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Từ 5 suất được freeship; từ 10 suất giảm 6%, từ 20 suất giảm 8%, từ 30 suất giảm 12%. Chỉ áp dụng một mức giảm cao nhất trên toàn bộ tiền hàng, gồm đồ uống và phần thêm; phí giao hàng không thuộc khoản giảm phần trăm."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Chọn cách nhận và kiểm tra người nhận"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Chọn Giao tận nơi hoặc Nhận tại quầy. Nếu giao tận nơi, chọn địa điểm NEU đang được phục vụ và nhập phòng hoặc vị trí nhận cụ thể. Kiểm tra họ tên, số điện thoại người nhận và bổ sung ghi chú khi cần. Khi đặt hộ, hãy sửa thông tin người nhận trước khi xác nhận."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Nhận ngay hoặc đặt hẹn"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Canteen phục vụ từ thứ Hai đến thứ Bảy, nghỉ Chủ nhật. Đặt ngay trong khung nhận đơn 07:30 đến 18:30; món xong sớm có thể được giao sớm. Nếu muốn nhận sau, chọn hẹn giờ trong khung phục vụ 07:30 đến 19:00, cách thời điểm đặt ít nhất 30 phút và trong hôm nay hoặc 7 ngày tiếp theo. Vào Chủ nhật, bạn có thể tạo đơn hẹn nhận vào ngày làm việc hợp lệ tiếp theo."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Xác nhận và thanh toán"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kiểm tra lại chi tiết rồi xác nhận đặt hàng. Tiền mặt hoặc VietQR được thanh toán khi nhận món theo phương thức đã chọn. Với tổng thanh toán từ 500.000đ sau ưu đãi và phí giao thực thu, hệ thống yêu cầu cọc 50% và nhân viên căn tin sẽ gọi xác nhận."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Trong phiên bản thử nghiệm hiện tại, bước đặt cọc chỉ là mô phỏng: chọn Đặt cọc, kiểm tra số tiền, rồi xác nhận đặt cọc mô phỏng. Không chuyển tiền thật theo mã QR mô phỏng. Phần còn lại được hiển thị rõ để thanh toán COD khi nhận."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Theo dõi và nhận món"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Theo dõi tiến trình trong Đơn hàng. Mỗi tài khoản chỉ có một đơn đang hoạt động; hãy hoàn tất đơn hiện tại trước khi tạo đơn mới. Khi nhận món, cung cấp đúng 4 số cuối mã đơn để nhân viên đối chiếu và thanh toán số tiền còn phải thu. Bạn có thể hủy đơn khi đơn vẫn đang chờ xác nhận."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Cần hỗ trợ? Liên hệ anh Hoàng Văn Quản Lý qua số 0812 852 613 để được giải đáp trước khi đặt hàng."}]}]}}'::jsonb,now()) ON CONFLICT DO NOTHING;
INSERT INTO articles(id,kind,status,draft,published,published_at) VALUES ('initial-neu70','news','published','{"title": "NEUFOOD gửi lời chúc mừng kỷ niệm 70 năm thành lập NEU", "summary": "NEUFood trân trọng gửi lời chúc mừng tới các thế hệ giảng viên, cán bộ, sinh viên và cựu sinh viên NEU nhân dấu mốc 70 năm thành lập.", "cover_url": "", "recruitment_roles": [], "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nhân dịp kỷ niệm 70 năm thành lập NEU, NEUFOOD trân trọng gửi những lời chúc tốt đẹp nhất tới tập thể nhà trường, các thế hệ giảng viên, cán bộ, sinh viên và cựu sinh viên."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Tự hào một chặng đường, trân trọng những người đồng hành"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bảy mươi năm là dấu mốc để cùng nhìn lại những nỗ lực bền bỉ trong học tập, giảng dạy và xây dựng cộng đồng. Với mỗi người từng gắn bó cùng NEU, ký ức về giảng đường, những người thầy, bạn bè và những ngày tuổi trẻ đều góp phần làm nên tình cảm đặc biệt dành cho mái trường."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "NEUFOOD xin gửi lời tri ân tới các thầy cô và cán bộ đã tận tâm đồng hành với người học; chúc các bạn sinh viên luôn giữ tinh thần chủ động, ham học hỏi và trách nhiệm với cộng đồng."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Đồng hành từ những điều gần gũi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Với NEUFOOD, sự đồng hành bắt đầu từ những bữa ăn trong khuôn viên trường: một giờ nghỉ thuận tiện hơn, một phần ăn được chuẩn bị chu đáo hơn và một trải nghiệm đặt món rõ ràng hơn. Chúng tôi mong muốn tiếp tục lắng nghe để cải thiện dịch vụ mỗi ngày, góp thêm sự thuận tiện vào nhịp sống học đường."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Chúc mừng NEU, vững bước trong chặng đường mới"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kính chúc nhà trường tiếp tục phát triển, chúc các thầy cô nhiều sức khỏe và nhiệt huyết; chúc các thế hệ sinh viên, cựu sinh viên luôn vững tin theo đuổi mục tiêu, lan tỏa những giá trị tích cực và gắn bó với cộng đồng NEU."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "NEUFOOD chúc mừng kỷ niệm 70 năm thành lập NEU! Cảm ơn thầy cô và các bạn đã cùng tạo nên một môi trường học tập giàu tinh thần kết nối, nơi mỗi trải nghiệm nhỏ đều có thể trở thành một kỷ niệm đẹp."}]}]}}'::jsonb,'{"title": "NEUFOOD gửi lời chúc mừng kỷ niệm 70 năm thành lập NEU", "summary": "NEUFood trân trọng gửi lời chúc mừng tới các thế hệ giảng viên, cán bộ, sinh viên và cựu sinh viên NEU nhân dấu mốc 70 năm thành lập.", "cover_url": "", "recruitment_roles": [], "body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nhân dịp kỷ niệm 70 năm thành lập NEU, NEUFOOD trân trọng gửi những lời chúc tốt đẹp nhất tới tập thể nhà trường, các thế hệ giảng viên, cán bộ, sinh viên và cựu sinh viên."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Tự hào một chặng đường, trân trọng những người đồng hành"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bảy mươi năm là dấu mốc để cùng nhìn lại những nỗ lực bền bỉ trong học tập, giảng dạy và xây dựng cộng đồng. Với mỗi người từng gắn bó cùng NEU, ký ức về giảng đường, những người thầy, bạn bè và những ngày tuổi trẻ đều góp phần làm nên tình cảm đặc biệt dành cho mái trường."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "NEUFOOD xin gửi lời tri ân tới các thầy cô và cán bộ đã tận tâm đồng hành với người học; chúc các bạn sinh viên luôn giữ tinh thần chủ động, ham học hỏi và trách nhiệm với cộng đồng."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Đồng hành từ những điều gần gũi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Với NEUFOOD, sự đồng hành bắt đầu từ những bữa ăn trong khuôn viên trường: một giờ nghỉ thuận tiện hơn, một phần ăn được chuẩn bị chu đáo hơn và một trải nghiệm đặt món rõ ràng hơn. Chúng tôi mong muốn tiếp tục lắng nghe để cải thiện dịch vụ mỗi ngày, góp thêm sự thuận tiện vào nhịp sống học đường."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Chúc mừng NEU, vững bước trong chặng đường mới"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kính chúc nhà trường tiếp tục phát triển, chúc các thầy cô nhiều sức khỏe và nhiệt huyết; chúc các thế hệ sinh viên, cựu sinh viên luôn vững tin theo đuổi mục tiêu, lan tỏa những giá trị tích cực và gắn bó với cộng đồng NEU."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "NEUFOOD chúc mừng kỷ niệm 70 năm thành lập NEU! Cảm ơn thầy cô và các bạn đã cùng tạo nên một môi trường học tập giàu tinh thần kết nối, nơi mỗi trải nghiệm nhỏ đều có thể trở thành một kỷ niệm đẹp."}]}]}}'::jsonb,now()) ON CONFLICT DO NOTHING;
COMMIT;
